                l = { begin: /\[/, end: /\]/, contains: [i, o, a, s, r, 'self'], relevance: 0 },
                c = /[A-Za-z0-9_-]+/,
                u = /"(\\"|[^"])*"/,
                d = /'[^']*'/,
                f = n.either(c, u, d),
